package com.fixmer.genesis.technology.server.remote;
import com.fixmer.genesis.technology.server.firstlaunch.*;import java.io.*;import java.nio.channels.*;import java.nio.file.*;import java.util.*;
/** Same-user owner bridge. Player UUID/root/verifiedIdentity inputs MUST come from actual ServerPlayer context. */
public final class ServerAccess88 {
 public static final Map<String,Set<String>> ROLES=Map.of("OBSERVER",Set.of("PING"),"PREPARER",Set.of("PING","STAGE"),"PUBLISHER",Set.of("PING","STAGE","OFFER","CANCEL"),"RESTARTER",Set.of("PING","RESTART","COMMIT","CONTINUE_WAIT","CLOSE"),"MAINTAINER",Set.of("PING","RESTART","STAGE","OFFER","CANCEL","COMMIT","CONTINUE_WAIT","CLOSE"));
 public static final Set<String> ROOT_ACTIONS=Set.of("PING","RESTART","STAGE","OFFER","COMMIT","CANCEL","CONTINUE_WAIT","CLOSE","SHUTDOWN","LOCAL_TEST_ON","LOCAL_TEST_OFF");
 private static final Set<String> FIELDS=Set.of("schema","run","revision","subjects","sequence","audit");
 public final Path root;private final byte[] key;private final String run;
 private ServerAccess88(Path p,byte[] k,String r){root=p;key=k;run=r;}
 private static IOException fail(String c){return new IOException("ACCESS88_"+c);}
 public static ServerAccess88 open(Path root)throws Exception{var admin=DedicatedAdmin75.open(root);root=admin.root;if(!Files.isRegularFile(root.resolve("owner88"),LinkOption.NOFOLLOW_LINKS))throw fail("NEW_OWNER_REQUIRED");byte[] k=FirstLaunchFiles.read(root.resolve("owner74.key"),32);if(!LocalApply67.verify(k,FirstLaunchFiles.read(root.resolve("owner88"),16384)).equals(Map.of("schema","88","run",admin.run.toString())))throw fail("NEW_OWNER_REQUIRED");return new ServerAccess88(root,k,admin.run.toString());}
 private interface Work<T>{T run(Map<String,String> s)throws Exception;}
 private <T>T locked(Work<T> f)throws Exception{Path p=FirstLaunchFiles.safe(root.resolve("access88.lock"));try(var c=FileChannel.open(p,StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){FirstLaunchFiles.privateMode(p);try(var l=c.tryLock(0,1,false)){if(l==null)throw fail("BUSY");return f.run(read());}}catch(OverlappingFileLockException e){throw fail("BUSY");}}
 private static long number(String s)throws IOException{if(s==null||!s.matches("0|[1-9][0-9]{0,12}"))throw fail("STATE");return Long.parseLong(s);}
 private Map<String,String> read()throws Exception{var s=new TreeMap<>(LocalApply67.verify(key,FirstLaunchFiles.read(root.resolve("access88.state"),65536)));if(!s.keySet().equals(FIELDS)||!s.get("schema").equals("88")||!s.get("run").equals(run)||number(s.get("revision"))>999999999999L||number(s.get("sequence"))>999999999999L)throw fail("STATE");subjects(s);String a=s.get("audit");if(a.length()>24000||!a.isEmpty()&&!a.endsWith("\n")||a.lines().count()>64)throw fail("STATE");return s;}
 private static TreeMap<String,String> subjects(Map<String,String> s)throws Exception{var out=new TreeMap<String,String>();String raw=s.get("subjects");if(raw.length()>16000||!raw.isEmpty()&&!raw.endsWith("\n"))throw fail("STATE");for(String line:raw.split("\n")){if(line.isEmpty())continue;String[] p=line.split("=",-1);if(p.length!=2||!UUID.fromString(p[0]).toString().equals(p[0])||!ROLES.containsKey(p[1])||out.put(p[0],p[1])!=null||out.size()>256)throw fail("STATE");}StringBuilder b=new StringBuilder();out.forEach((k,v)->b.append(k).append('=').append(v).append('\n'));if(!b.toString().equals(raw))throw fail("STATE");return out;}
 private void save(Map<String,String> s)throws Exception{FirstLaunchFiles.write(root.resolve("access88.state"),LocalApply67.sign(key,s),true);}
 private static void event(Map<String,String> s,String actor,String target,String action,String outcome,UUID request,String label)throws Exception{long n=number(s.get("sequence"))+1;if(n>999999999999L)throw fail("LIMIT");String row=n+"|"+System.currentTimeMillis()+"|"+actor+"|"+target+"|"+action+"|"+outcome+"|"+request+"|"+label+"\n";var rows=new ArrayList<>(s.get("audit").lines().toList());rows.add(row.stripTrailing());if(rows.size()>64)rows.remove(0);s.put("sequence",Long.toString(n));s.put("audit",String.join("\n",rows)+"\n");}
 private static boolean allowed(Map<String,String> s,UUID actor,boolean root,boolean verifiedIdentity,String action)throws Exception{return verifiedIdentity&&(root?ROOT_ACTIONS.contains(action):ROLES.getOrDefault(subjects(s).getOrDefault(actor.toString(),"NONE"),Set.of()).contains(action));}
 public Map<String,String> view(UUID actor,boolean root,boolean verifiedIdentity)throws Exception{return locked(s->{if(!allowed(s,actor,root,verifiedIdentity,"PING"))throw fail("DENIED");return Map.of("schema","88","revision",s.get("revision"),"role",root?"ROOT":subjects(s).getOrDefault(actor.toString(),"NONE"),"manage",Boolean.toString(root&&verifiedIdentity),"subjects",root?s.get("subjects"):"","audit",String.join("\n",s.get("audit").lines().skip(Math.max(0,s.get("audit").lines().count()-24)).toList()),"actions",String.join(",",new TreeSet<>(root?ROOT_ACTIONS:ROLES.getOrDefault(subjects(s).getOrDefault(actor.toString(),"NONE"),Set.of()))));});}
 public void change(UUID actor,boolean root,boolean verifiedIdentity,UUID target,String role,long expected,UUID request)throws Exception{if(!root||!verifiedIdentity)throw fail("DENIED");if(request.equals(new UUID(0,0))||target.equals(new UUID(0,0))||!role.equals("NONE")&&!ROLES.containsKey(role))throw fail("INPUT");locked(s->{if(number(s.get("revision"))!=expected)throw fail("STALE");var users=subjects(s);if(role.equals("NONE"))users.remove(target.toString());else users.put(target.toString(),role);if(users.size()>256)throw fail("LIMIT");long revision=expected+1;if(revision>999999999999L)throw fail("LIMIT");var b=new StringBuilder();users.forEach((k,v)->b.append(k).append('=').append(v).append('\n'));s.put("subjects",b.toString());s.put("revision",Long.toString(revision));event(s,actor.toString(),target.toString(),role.equals("NONE")?"REVOKE":"GRANT","CHANGED",request,role);save(s);return null;});}
 public Map<String,String> access(UUID actor,boolean root,boolean verifiedIdentity)throws Exception{return view(actor,root,verifiedIdentity);}
 public void queue(UUID actor,boolean rootPermission,boolean verifiedIdentity,long authorizedAt,UUID nonce,String action,String label)throws Exception{queue153(actor,rootPermission,verifiedIdentity,authorizedAt,nonce,action,label,"");}
 public void queue153(UUID actor,boolean rootPermission,boolean verifiedIdentity,long authorizedAt,UUID nonce,String action,String label,String fingerprint)throws Exception{if(!fingerprint.isEmpty()&&!fingerprint.matches("[a-f0-9]{64}"))throw fail("INPUT");long now=System.currentTimeMillis();if(now<authorizedAt-2000||now-authorizedAt>5000)throw fail("SESSION_STALE");if(!label.matches("[A-Za-z0-9_-]{1,40}")||action.equals("PING"))throw fail("INPUT");locked(s->{if(!allowed(s,actor,rootPermission,verifiedIdentity,action))throw fail("DENIED");var admin=DedicatedAdmin75.open(root);String gen=admin.view().get("generation");var p=new TreeMap<String,String>();p.putAll(Map.of("schema","88","run",run,"actor",actor.toString(),"root",Boolean.toString(rootPermission),"revision",s.get("revision"),"generation",gen,"request",nonce.toString(),"action",action,"label",label,"issued",Long.toString(authorizedAt)));p.put("expires",Long.toString(authorizedAt+15000));if(!fingerprint.isEmpty())p.put("device153",fingerprint);event(s,actor.toString(),actor.toString(),action,"REQUESTED",nonce,label);save(s);try{admin.submitRemote88(nonce,action,label,gen,Base64.getEncoder().encodeToString(LocalApply67.sign(key,p)));}catch(Exception e){event(s,actor.toString(),actor.toString(),action,"QUEUE_REFUSED",nonce,label);save(s);throw e;}event(s,actor.toString(),actor.toString(),action,"QUEUED",nonce,label);save(s);return null;});}
}
